                if (i == pair[0] and j == pair[1]) or (i == pair[2] and j == pair[3]):
                    aisle_matrix[i][j] += 1

    # Find the most effective position for the horizontal aisles
    horizontal_positions = []
    for i in range(M + K):
        # If there is at least one aisle in the row, add the position to the list
