def select_volunteers(n, m, applicants):
    # Sort the applicants by test score in descending order
    sorted_applicants = sorted(applicants, key=lambda x: x[1], reverse=True)
    # Calculate the interview score cutoff
    cutoff = int(m * 1.5)
    # Initialize the list of qualified applicants
    qualified_applicants = []
    # Iterate through the sorted applicants and add them to the qualified list if they meet the cutoff
    for applicant in sorted_applicants:
        if applicant[1] >= cutoff:
            qualified_applicants.append(applicant)
    # Return the interview score cutoff and the list of qualified applicants
    return (cutoff, qualified_applicants)

def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if n > last:
        return 0
    if n == last:
        return 1
    count = 0
    for i in range(n, last):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

